#include <array>
#include <cassert>
#include <cstdint>
#include <cstring>

#include "../wled00/cinema/cinema_spi_protocol.h"

using cinema::protocol::ColorFormat;
using cinema::protocol::FrameRgbHeader;
using cinema::protocol::FrameRgbView;
using cinema::protocol::MessageType;
using cinema::protocol::NodeRole;
using cinema::protocol::PacketHeader;
using cinema::protocol::PacketStatus;
using cinema::protocol::PacketView;

// AI: below section was generated by an AI
// Host checks cover wire integrity, fixed SPI mailbox slots and the versioned RGB frame contract.
int main() {
  constexpr uint8_t crcInput[] = {'1', '2', '3', '4', '5', '6', '7', '8', '9'};
  assert(cinema::protocol::crc32c(crcInput, sizeof(crcInput)) == 0xE3069283U);

  const std::array<uint8_t, 6> commandPayload{{0, 1, 0, 2, 3, 0}};
  PacketHeader commandHeader;
  commandHeader.type = MessageType::Heartbeat;
  commandHeader.flags = 0xA5;
  commandHeader.source = NodeRole::CameraLeft;
  commandHeader.target = NodeRole::Controller;
  commandHeader.sequence = 0x12345678U;
  commandHeader.bootId = 0x9ABCDEF0U;
  commandHeader.requestId = 42;

  std::array<uint8_t, cinema::protocol::MAX_PACKET_SIZE> encodedPacket{};
  size_t encodedPacketSize = 0;
  assert(cinema::protocol::encodePacket(commandHeader, commandPayload.data(), commandPayload.size(), encodedPacket.data(), encodedPacket.size(), &encodedPacketSize) == PacketStatus::Ok);

  PacketView packet;
  assert(cinema::protocol::decodePacket(encodedPacket.data(), encodedPacketSize, &packet) == PacketStatus::Ok);
  assert(packet.header.type == MessageType::Heartbeat);
  assert(packet.header.sequence == commandHeader.sequence);
  assert(packet.header.bootId == commandHeader.bootId);
  assert(packet.header.requestId == commandHeader.requestId);
  assert(packet.payloadSize == commandPayload.size());
  assert(memcmp(packet.payload, commandPayload.data(), commandPayload.size()) == 0);
  encodedPacket[2] = 1;
  assert(cinema::protocol::decodePacket(encodedPacket.data(), encodedPacketSize, &packet) == PacketStatus::IncompatibleVersion);
  encodedPacket[2] = cinema::protocol::PROTOCOL_VERSION_MAJOR;

  std::array<uint8_t, cinema::protocol::MAX_PACKET_SIZE> corruptedPacket = encodedPacket;
  corruptedPacket[cinema::protocol::PACKET_HEADER_SIZE] ^= 0x01;
  assert(cinema::protocol::decodePacket(corruptedPacket.data(), encodedPacketSize, &packet) == PacketStatus::CrcMismatch);

  std::array<uint8_t, cinema::spi::SLOT_SIZE> spiSlot{};
  cinema::spi::SlotView slot;
  assert(cinema::spi::encodeSlot(nullptr, 0, cinema::spi::SLOT_FLAG_BUSY, 10, spiSlot.data(), spiSlot.size()) == cinema::spi::SlotStatus::Ok);
  assert(cinema::spi::decodeSlot(spiSlot.data(), spiSlot.size(), &slot) == cinema::spi::SlotStatus::Empty);
  assert(slot.isBusy());
  assert(!slot.hasPacket());

  assert(cinema::spi::encodeSlot(encodedPacket.data(), encodedPacketSize, 0, 11, spiSlot.data(), spiSlot.size()) == cinema::spi::SlotStatus::Ok);
  assert(cinema::spi::decodeSlot(spiSlot.data(), spiSlot.size(), &slot) == cinema::spi::SlotStatus::Ok);
  assert(slot.hasPacket());
  assert(slot.sequence == 11);
  assert(slot.packet.header.type == MessageType::Heartbeat);
  assert(slot.packet.payloadSize == commandPayload.size());

  spiSlot[8] ^= 0x01;
  assert(cinema::spi::decodeSlot(spiSlot.data(), spiSlot.size(), &slot) == cinema::spi::SlotStatus::HeaderCrcMismatch);
  spiSlot[8] ^= 0x01;
  spiSlot[cinema::spi::SLOT_HEADER_SIZE + cinema::protocol::PACKET_HEADER_SIZE] ^= 0x01;
  assert(cinema::spi::decodeSlot(spiSlot.data(), spiSlot.size(), &slot) == cinema::spi::SlotStatus::PacketInvalid);
  assert(slot.packetStatus == PacketStatus::CrcMismatch);

  const std::array<uint8_t, 9> colors{{1, 2, 3, 4, 5, 6, 7, 8, 9}};
  FrameRgbHeader frameHeader;
  frameHeader.configGeneration = 7;
  frameHeader.frameId = 99;
  frameHeader.captureTimeUs = 123456789ULL;
  frameHeader.fpsQ8_8 = 30U << 8;
  frameHeader.slotCount = 3;
  frameHeader.colorFormat = ColorFormat::Rgb24;
  frameHeader.flags = 0x01;
  frameHeader.controllerBootId = 0x12345678;
  frameHeader.pollSequence = UINT32_MAX;

  std::array<uint8_t, cinema::protocol::MAX_PAYLOAD_SIZE> framePayload{};
  size_t framePayloadSize = 0;
  assert(cinema::protocol::encodeFrameRgbPayload(frameHeader, colors.data(), colors.size(), framePayload.data(), framePayload.size(), &framePayloadSize) == PacketStatus::Ok);

  FrameRgbView frame;
  assert(cinema::protocol::decodeFrameRgbPayload(framePayload.data(), framePayloadSize, &frame) == PacketStatus::Ok);
  assert(frame.header.configGeneration == frameHeader.configGeneration);
  assert(frame.header.frameId == frameHeader.frameId);
  assert(frame.header.captureTimeUs == frameHeader.captureTimeUs);
  assert(frame.header.slotCount == frameHeader.slotCount);
  assert(frame.header.controllerBootId == frameHeader.controllerBootId);
  assert(frame.header.pollSequence == frameHeader.pollSequence);
  assert(memcmp(frame.colors, colors.data(), colors.size()) == 0);
  return 0;
}
